from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 matmul_kernel_param_0,
    .param .u64 matmul_kernel_param_1,
    .param .u64 matmul_kernel_param_2,
    .param .u32 matmul_kernel_param_3
)
{
    .reg .pred %pt, %pk, %pmore;
    .reg .u32 %tx, %ty, %tlin, %bx, %by, %n, %t, %k, %m, %kg, %kk, %ng, %aoff, %boff, %tn;
    .reg .u64 %ap, %bp, %cp, %sa, %sb, %off, %gaddr, %saddr, %asbase, %bsbase, %rstride, %curo, %nxto, %tmpo;
    .reg .f32 %acc<16>, %av<4>, %bv<4>;
    .shared .align 16 .b8 As[8192];
    .shared .align 16 .b8 Bs[8192];
    ld.param.u64 %ap, [matmul_kernel_param_0];
    ld.param.u64 %bp, [matmul_kernel_param_1];
    ld.param.u64 %cp, [matmul_kernel_param_2];
    ld.param.u32 %n, [matmul_kernel_param_3];
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;
    // tid = ty * 16 + tx
    shl.b32 %tlin, %ty, 4;
    add.u32 %tlin, %tlin, %tx;
    mov.u64 %sa, As;
    mov.u64 %sb, Bs;
    // asbase = &As[ty*4][0] (byte offset ty*256) ; bsbase = &Bs[0][tx*4] (byte offset tx*16)
    shl.b32 %aoff, %ty, 8;
    cvt.u64.u32 %off, %aoff;
    add.u64 %asbase, %sa, %off;
    shl.b32 %boff, %tx, 4;
    cvt.u64.u32 %off, %boff;
    add.u64 %bsbase, %sb, %off;
    mov.f32 %acc0, 0f00000000;
    mov.f32 %acc1, 0f00000000;
    mov.f32 %acc2, 0f00000000;
    mov.f32 %acc3, 0f00000000;
    mov.f32 %acc4, 0f00000000;
    mov.f32 %acc5, 0f00000000;
    mov.f32 %acc6, 0f00000000;
    mov.f32 %acc7, 0f00000000;
    mov.f32 %acc8, 0f00000000;
    mov.f32 %acc9, 0f00000000;
    mov.f32 %acc10, 0f00000000;
    mov.f32 %acc11, 0f00000000;
    mov.f32 %acc12, 0f00000000;
    mov.f32 %acc13, 0f00000000;
    mov.f32 %acc14, 0f00000000;
    mov.f32 %acc15, 0f00000000;
    // double-buffer state: %curo = compute buffer byte offset, %nxto = staging buffer byte offset
    mov.u64 %curo, 0;
    mov.u64 %nxto, 4096;
    mov.u32 %t, 0;
    // ---- prologue: async stage tile t=0 into buffer 0 ----
    // A: m = tid >> 2, kg = tid & 3 ; A[by*64+m][kg*4 .. +3]
    shr.u32 %m, %tlin, 2;
    and.b32 %kg, %tlin, 3;
    shl.b32 %aoff, %by, 6;
    add.u32 %aoff, %aoff, %m;
    mul.lo.u32 %aoff, %aoff, %n;
    shl.b32 %kg, %kg, 2;
    add.u32 %aoff, %aoff, %kg;
    cvt.u64.u32 %off, %aoff;
    shl.b64 %off, %off, 2;
    add.u64 %gaddr, %ap, %off;
    shl.b32 %aoff, %m, 4;
    add.u32 %aoff, %aoff, %kg;
    cvt.u64.u32 %off, %aoff;
    shl.b64 %off, %off, 2;
    add.u64 %saddr, %sa, %off;
    cp.async.cg.shared.global [%saddr], [%gaddr], 16;
    // B: kk = tid >> 4, ng = tid & 15 ; B[kk][bx*64 + ng*4 .. +3]
    shr.u32 %kk, %tlin, 4;
    and.b32 %ng, %tlin, 15;
    mul.lo.u32 %boff, %kk, %n;
    shl.b32 %aoff, %bx, 6;
    add.u32 %boff, %boff, %aoff;
    shl.b32 %ng, %ng, 2;
    add.u32 %boff, %boff, %ng;
    cvt.u64.u32 %off, %boff;
    shl.b64 %off, %off, 2;
    add.u64 %gaddr, %bp, %off;
    shl.b32 %boff, %kk, 6;
    add.u32 %boff, %boff, %ng;
    cvt.u64.u32 %off, %boff;
    shl.b64 %off, %off, 2;
    add.u64 %saddr, %sb, %off;
    cp.async.cg.shared.global [%saddr], [%gaddr], 16;
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
$L_loop_t:
    setp.lt.u32 %pt, %t, %n;
    @!%pt bra $L_done;
    // ---- issue async stage of next tile (t+16) into the staging buffer ----
    add.u32 %tn, %t, 16;
    setp.lt.u32 %pmore, %tn, %n;
    @!%pmore bra $L_no_prefetch;
    // stage A tile for t+16
    shr.u32 %m, %tlin, 2;
    and.b32 %kg, %tlin, 3;
    shl.b32 %aoff, %by, 6;
    add.u32 %aoff, %aoff, %m;
    mul.lo.u32 %aoff, %aoff, %n;
    add.u32 %aoff, %aoff, %tn;
    shl.b32 %kg, %kg, 2;
    add.u32 %aoff, %aoff, %kg;
    cvt.u64.u32 %off, %aoff;
    shl.b64 %off, %off, 2;
    add.u64 %gaddr, %ap, %off;
    shl.b32 %aoff, %m, 4;
    add.u32 %aoff, %aoff, %kg;
    cvt.u64.u32 %off, %aoff;
    shl.b64 %off, %off, 2;
    add.u64 %saddr, %sa, %off;
    add.u64 %saddr, %saddr, %nxto;
    cp.async.cg.shared.global [%saddr], [%gaddr], 16;
    // stage B tile for t+16
    shr.u32 %kk, %tlin, 4;
    and.b32 %ng, %tlin, 15;
    add.u32 %boff, %tn, %kk;
    mul.lo.u32 %boff, %boff, %n;
    shl.b32 %aoff, %bx, 6;
    add.u32 %boff, %boff, %aoff;
    shl.b32 %ng, %ng, 2;
    add.u32 %boff, %boff, %ng;
    cvt.u64.u32 %off, %boff;
    shl.b64 %off, %off, 2;
    add.u64 %gaddr, %bp, %off;
    shl.b32 %boff, %kk, 6;
    add.u32 %boff, %boff, %ng;
    cvt.u64.u32 %off, %boff;
    shl.b64 %off, %off, 2;
    add.u64 %saddr, %sb, %off;
    add.u64 %saddr, %saddr, %nxto;
    cp.async.cg.shared.global [%saddr], [%gaddr], 16;
$L_no_prefetch:
    cp.async.commit_group;
    cp.async.wait_group 1;
    bar.sync 0;
    // ---- inner loop: each thread accumulates a 4x4 register micro-tile from the current buffer ----
    mov.u32 %k, 0;
$L_loop_k:
    setp.lt.u32 %pk, %k, 16;
    @!%pk bra $L_k_done;
    // bv = Bs_cur[k][tx*4 .. +3] (vectorized)
    shl.b32 %boff, %k, 8;
    cvt.u64.u32 %off, %boff;
    add.u64 %gaddr, %bsbase, %off;
    add.u64 %gaddr, %gaddr, %curo;
    ld.shared.v4.f32 {%bv0, %bv1, %bv2, %bv3}, [%gaddr];
    // av0..av3 = As_cur[ty*4+i][k] (broadcast within half-warp)
    shl.b32 %aoff, %k, 2;
    cvt.u64.u32 %off, %aoff;
    add.u64 %gaddr, %asbase, %off;
    add.u64 %gaddr, %gaddr, %curo;
    ld.shared.f32 %av0, [%gaddr];
    ld.shared.f32 %av1, [%gaddr+64];
    ld.shared.f32 %av2, [%gaddr+128];
    ld.shared.f32 %av3, [%gaddr+192];
    fma.rn.f32 %acc0, %av0, %bv0, %acc0;
    fma.rn.f32 %acc1, %av0, %bv1, %acc1;
    fma.rn.f32 %acc2, %av0, %bv2, %acc2;
    fma.rn.f32 %acc3, %av0, %bv3, %acc3;
    fma.rn.f32 %acc4, %av1, %bv0, %acc4;
    fma.rn.f32 %acc5, %av1, %bv1, %acc5;
    fma.rn.f32 %acc6, %av1, %bv2, %acc6;
    fma.rn.f32 %acc7, %av1, %bv3, %acc7;
    fma.rn.f32 %acc8, %av2, %bv0, %acc8;
    fma.rn.f32 %acc9, %av2, %bv1, %acc9;
    fma.rn.f32 %acc10, %av2, %bv2, %acc10;
    fma.rn.f32 %acc11, %av2, %bv3, %acc11;
    fma.rn.f32 %acc12, %av3, %bv0, %acc12;
    fma.rn.f32 %acc13, %av3, %bv1, %acc13;
    fma.rn.f32 %acc14, %av3, %bv2, %acc14;
    fma.rn.f32 %acc15, %av3, %bv3, %acc15;
    add.u32 %k, %k, 1;
    bra $L_loop_k;
$L_k_done:
    bar.sync 0;
    // swap compute/staging buffers
    mov.u64 %tmpo, %curo;
    mov.u64 %curo, %nxto;
    mov.u64 %nxto, %tmpo;
    add.u32 %t, %t, 16;
    bra $L_loop_t;
$L_done:
    // ---- store 4x4 micro-tile: C[by*64+ty*4+i][bx*64+tx*4 .. +3] ----
    shl.b32 %aoff, %by, 6;
    shl.b32 %boff, %ty, 2;
    add.u32 %aoff, %aoff, %boff;
    mul.lo.u32 %aoff, %aoff, %n;
    shl.b32 %boff, %bx, 6;
    add.u32 %aoff, %aoff, %boff;
    shl.b32 %boff, %tx, 2;
    add.u32 %aoff, %aoff, %boff;
    cvt.u64.u32 %off, %aoff;
    shl.b64 %off, %off, 2;
    add.u64 %gaddr, %cp, %off;
    cvt.u64.u32 %off, %n;
    shl.b64 %rstride, %off, 2;
    st.global.v4.f32 [%gaddr], {%acc0, %acc1, %acc2, %acc3};
    add.u64 %gaddr, %gaddr, %rstride;
    st.global.v4.f32 [%gaddr], {%acc4, %acc5, %acc6, %acc7};
    add.u64 %gaddr, %gaddr, %rstride;
    st.global.v4.f32 [%gaddr], {%acc8, %acc9, %acc10, %acc11};
    add.u64 %gaddr, %gaddr, %rstride;
    st.global.v4.f32 [%gaddr], {%acc12, %acc13, %acc14, %acc15};
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        n = A.shape[0]
        C = torch.empty((n, n), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        tile = 16
        cta_tile = 64
        grid = ((n + cta_tile - 1) // cta_tile, (n + cta_tile - 1) // cta_tile, 1)
        module.launch(
            "matmul_kernel",
            grid=grid,
            block=(tile, tile, 1),
            arguments=[A, B, C, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

